window.KnowledgeArticleRegistry["processor-overview"]={"title":"ESP32-Prozessorfamilien im Vergleich","summary":"Die ESP32-Bezeichnung beschreibt zuerst den Chip. Ein Board ergaenzt ihn um Flash, USB, Spannungsversorgung, Antenne und oft Display, Sensoren oder weitere Anschluesse.","sections":[{"heading":"Erst die Aufgabe, dann der Chip","paragraphs":["Die Buchstaben sind keine Reihenfolge von gut nach schlecht. C steht vor allem fuer kompakte, vernetzte RISC-V-Controller, S fuer umfangreichere WLAN-Controller, H fuer 802.15.4 ohne WLAN und P fuer einen leistungsstarken Prozessor ohne eingebauten Funk. Entscheidend sind Funkweg, Energieversorgung, lokale Bedienung und die benoetigten Anschluesse."]},{"heading":"Familienuebersicht","table":{"headers":["Familie","Funk","Fuer Hausautomation besonders passend","Einordnung"],"rows":[["ESP32 (klassisch)","WLAN 2,4 GHz, Bluetooth Classic und BLE","Bestehende Maker-Projekte, einfache WLAN-Nodes","Sehr weit verbreitet; fuer neue Projekte nur waehlen, wenn ein konkretes Board oder Beispiel dafuer spricht."],["ESP32-S2","WLAN 2,4 GHz","WLAN-Sensor, USB-Geraet, einfache lokale Webseite","Kein Bluetooth und kein Zigbee/Thread."],["ESP32-S3","WLAN 2,4 GHz, BLE","Touchdisplay, lokale Weboberflaeche, Audio, Kamera oder mehr lokale Logik","Gute Wahl fuer sichtbare, interaktive Home Nodes; kein Zigbee/Thread."],["ESP32-C2","WLAN 2,4 GHz, BLE","Sehr kleine, preiswerte WLAN-Sensoren oder Aktoren","Weniger Reserven und Anschluesse; nicht fuer Display- oder umfangreiche Projekte."],["ESP32-C3","WLAN 2,4 GHz, BLE","Einfacher WLAN-Home-Node, Sensor, Relais oder lokale Statusseite","Solider Einstieg fuer WLAN. C3 hat kein Zigbee und kein Thread."],["ESP32-C5","Dual-Band WLAN 6 (2,4/5 GHz), BLE","Anforderungsvolle WLAN-Umgebungen oder 5-GHz-WLAN","Kein Zigbee/Thread. Fuer einen ersten Home-Node meist mehr als erforderlich."],["ESP32-C6","WLAN 6 (2,4 GHz), BLE, 802.15.4","WLAN-Node mit spaeterem Zigbee- oder Thread-Pfad; versorgte Bridge oder Gateway","Der flexible Funkchip: 802.15.4 ist die Grundlage fuer Zigbee und Thread. Funk-Koexistenz muss im Projekt bewusst geplant werden."],["ESP32-C61","WLAN 6 (2,4 GHz), BLE","Moderne WLAN-Sensoren, Aktoren und energieoptimierte WLAN-Nodes","Kein Zigbee/Thread; moderne Alternative im WLAN-Zweig."],["ESP32-H2","BLE, 802.15.4 Zigbee/Thread","Batterie-Sensor oder Aktor als Zigbee-/Thread-Endgeraet","Kein WLAN. Ein H2 kann keine lokale WLAN-Webseite anbieten und braucht fuer den Weg ins Netzwerk einen passenden Koordinator oder eine Bridge."],["ESP32-P4","kein eingebauter Funk","Grosse lokale Bedienoberflaechen, Kamera, Multimedia oder leistungsfaehige Steuerung","Funk kommt bei Bedarf von einem zusaetzlichen C-, S- oder H-Chip. Kein Einstiegschip fuer einen einzelnen WLAN-Sensor."]]}},{"heading":"Schnellauswahl fuer das Lernprojekt","table":{"headers":["Wenn du moechtest ...","sinnvoller Start"],"rows":[["Temperatur messen und die Werte im Browser des Heimnetzes sehen","C3, S3 oder C6 als WLAN-Home-Node."],["Ein Display, Touch oder eine umfangreiche lokale Ansicht","S3; bei sehr anspruchsvoller Grafik oder Kamera spaeter P4 mit getrenntem Funkchip."],["Einen moeglichst sparsamen Batterie-Sensor im Zigbee-Netz","H2 als schlafendes Endgeraet plus vorhandener Zigbee-Koordinator."],["Heute WLAN nutzen, Zigbee oder Thread aber als Lernpfad offenhalten","C6. Erst den WLAN-Teil sauber bauen, dann den 802.15.4-Pfad gezielt ergaenzen."],["Viele Zigbee-Geraete mit einer lokalen Oberflaeche verbinden","Eine dauerhaft versorgte Bridge; bei anspruchsvolleren Varianten ein S3 plus H2 als getrennte Funk- und Bedienkomponenten."]]}},{"heading":"Akku und Funk realistisch beurteilen","paragraphs":["Eine Chipfamilie allein bestimmt nicht die Batterielaufzeit. Entscheidend sind Messintervall, Schlafdauer, Sendezeit, Sensor und die Rolle im Funknetz. Ein batteriebetriebenes Zigbee-Geraet ist normalerweise ein schlafendes Endgeraet; ein Router oder Koordinator muss dagegen erreichbar bleiben und wird typischerweise dauerhaft versorgt. WLAN kann ebenfalls sparsam sein, wenn ein Node nur selten aufwacht und sendet, braucht aber fuer eine staendig erreichbare lokale Webseite deutlich mehr Energie."]},{"heading":"Was die Tabelle nicht behauptet","paragraphs":["Es gibt keine allgemeine ESP32-C-Familie und aktuell keine ESP32-S6-Familie. C5 und C61 gibt es, P4 ebenfalls. Die Tabelle ist eine Orientierung, keine Freigabeliste. Ob ein konkretes Board fuer GerNetiX flashbar und passend ist, pruefst du anschliessend in Unterstuetzte Boards anhand der exakten Boardvariante, ihres Flash-Speichers und der Anschluesse."]}],"actions":[{"label":"Unterstuetzte Boards ansehen","route":"/hilfe/#supported-devices"}],"relatedTopics":["supported-devices","provision-new-board","update-profiles"],"access":"premium"};
